let browserSessionToken: string | undefined;

export function setBrowserSessionToken(token: string): void {
  browserSessionToken = token;
}

export function clearBrowserSessionToken(): void {
  browserSessionToken = undefined;
}

export async function apiFetch(
  input: string, init: RequestInit = {},
): Promise<Response> {
  const headers = new Headers(init.headers);
  if (browserSessionToken !== undefined) {
    headers.set('x-stata-browser-session', browserSessionToken);
  }
  return globalThis.fetch(input, { ...init, headers });
}

export type ApiEventStreamEvent = {
  readonly event: string;
  readonly id?: string;
  readonly data: string;
};

export async function consumeApiEventStream(
  url: string,
  handlers: {
    readonly onOpen: () => void;
    readonly onEvent: (event: ApiEventStreamEvent) => void;
  },
  signal: AbortSignal,
): Promise<void> {
  const response = await apiFetch(url, {
    headers: { accept: 'text/event-stream' },
    signal,
  });
  if (!response.ok || response.body === null) {
    throw new Error(`Event stream rejected with status ${response.status}`);
  }
  handlers.onOpen();
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let pending = '';
  const dispatchBlock = (block: string): void => {
    let event = 'message';
    let id: string | undefined;
    const data: string[] = [];
    for (const rawLine of block.split('\n')) {
      const line = rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine;
      if (line.startsWith(':') || line.length === 0) continue;
      const separator = line.indexOf(':');
      const field = separator < 0 ? line : line.slice(0, separator);
      let value = separator < 0 ? '' : line.slice(separator + 1);
      if (value.startsWith(' ')) value = value.slice(1);
      if (field === 'event') event = value;
      else if (field === 'id') id = value;
      else if (field === 'data') data.push(value);
    }
    if (data.length === 0) return;
    handlers.onEvent({ event, ...(id === undefined ? {} : { id }), data: data.join('\n') });
  };
  while (true) {
    const chunk = await reader.read();
    pending += decoder.decode(chunk.value, { stream: !chunk.done });
    pending = pending.replaceAll('\r\n', '\n');
    let boundary = pending.indexOf('\n\n');
    while (boundary >= 0) {
      dispatchBlock(pending.slice(0, boundary));
      pending = pending.slice(boundary + 2);
      boundary = pending.indexOf('\n\n');
    }
    if (chunk.done) break;
  }
  if (pending.trim().length > 0) dispatchBlock(pending);
}

