export async function getMeta(
  baseUrl: string, signal?: AbortSignal,
): Promise<MetaResponse> {
  const response = await globalThis.fetch(
    `${baseUrl}/api/v1/meta`,
    signal === undefined ? {} : { signal },
  );
  if (!response.ok) throw new Error(`Meta request failed with ${response.status}`);
  return await response.json() as MetaResponse;
}

export async function exchangeBrowserSession(
  baseUrl: string, bootstrapNonce: string, signal?: AbortSignal,
): Promise<SessionExchangeReceiptResponse> {
  const response = await globalThis.fetch(`${baseUrl}/api/v1/session/exchange`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ bootstrap_nonce: bootstrapNonce }),
    ...(signal === undefined ? {} : { signal }),
  });
  if (!response.ok) throw new Error(`Session exchange failed with ${response.status}`);
  return await response.json() as SessionExchangeReceiptResponse;
}

export type CommandEnvelope = WorkspaceCreateEnvelope | MessageSubmitEnvelope | WaitingAnswerEnvelope | TurnPauseRequestEnvelope | ResearchPathBranchEnvelope;
export type ApiResult<T> =
  | { readonly ok: true; readonly status: number; readonly data: T }
  | { readonly ok: false; readonly status: number; readonly error: ErrorResponse };

export async function submitCommand(
  baseUrl: string,
  command: CommandEnvelope,
  signal?: AbortSignal,
): Promise<ApiResult<CommandReceiptResponse>> {
  const response = await apiFetch(`${baseUrl}/api/v1/commands`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(command),
    ...(signal === undefined ? {} : { signal }),
  });
  const payload: unknown = await response.json();
  if (response.ok) {
    return { ok: true, status: response.status, data: payload as CommandReceiptResponse };
  }
  return { ok: false, status: response.status, error: payload as ErrorResponse };
}

