export type JournalQuery = {
  readonly cursor?: string;
  readonly pageSize?: number;
  readonly sort?: 'asc' | 'desc';
  readonly turnId?: string;
};

export async function getJournalEntries(
  baseUrl: string, workspaceId: string, query: JournalQuery = {},
  signal?: AbortSignal,
): Promise<ApiResult<JournalEntryPageResponse>> {
  const workspace = encodeURIComponent(workspaceId);
  const search = new URLSearchParams();
  if (query.cursor !== undefined) search.set('cursor', query.cursor);
  if (query.pageSize !== undefined) search.set('page_size', String(query.pageSize));
  if (query.sort !== undefined) search.set('sort', query.sort);
  if (query.turnId !== undefined) search.set('turn_id', query.turnId);
  const suffix = search.size === 0 ? '' : `?${search.toString()}`;
  const response = await apiFetch(
    `${baseUrl}/api/v1/workspaces/${workspace}/journal-entries${suffix}`,
    signal === undefined ? {} : { signal },
  );
  const payload: unknown = await response.json();
  if (response.ok) return { ok: true, status: response.status, data: payload as JournalEntryPageResponse };
  return { ok: false, status: response.status, error: payload as ErrorResponse };
}

